    emoji = '🏗️'; label = 'Pedido de infra' + (msg.autor && msg.autor !== '0' ? ' — ' + nomePessoa(C, emp, msg.autor) : '');
    rota = { grupo: C.param.grupo_dono, marcar: [], nome: null, shopping: loc ? loc.nome : 'Local não identificado' };
  } else if (ev === 'SEMTEC') {
