      const t = h >= 24 ? Math.floor(h / 24) + 'd ' + (h % 24) + 'h' : h + 'h';
      emoji = msg.escalar ? '🚨' : '⚠️'; label = 'Chamado segue sem técnico há ' + t + (msg.escalar ? ' (escalado)' : '');
